from collections import defaultdict
def transform(grid):
    H=len(grid);W=len(grid[0]);bg=0
    seen=set();comps=[]
    for r in range(H):
        for c in range(W):
            if grid[r][c]==bg or (r,c) in seen:continue
            col=grid[r][c];st=[(r,c)];seen.add((r,c));px=[]
            while st:
                x,y=st.pop();px.append((x,y))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    nx,ny=x+dx,y+dy
                    if 0<=nx<H and 0<=ny<W and (nx,ny) not in seen and grid[nx][ny]==col:
                        seen.add((nx,ny));st.append((nx,ny))
            comps.append((col,px))
    out=[row[:] for row in grid]
    by=defaultdict(list)
    for col,px in comps:by[col].append(px)
    def barea(g):
        rs=[p[0] for p in g];cs=[p[1] for p in g]
        return (max(rs)-min(rs)+1)*(max(cs)-min(cs)+1)
    for col,gs in by.items():
        if len(gs)<2:continue
        ba=[barea(g) for g in gs];m=max(ba)
        if ba.count(m)!=1:continue
        src=gs[ba.index(m)]
        rs=[p[0] for p in src];cs=[p[1] for p in src]
        sr0,sc0,sr1,sc1=min(rs),min(cs),max(rs),max(cs)
        sh=sr1-sr0+1;sw=sc1-sc0+1
        for g in gs:
            if barea(g)>=m:continue
            gr=[p[0] for p in g];gc=[p[1] for p in g]
            tr=round((min(gr)+max(gr))/2-(sh-1)/2);tc=round((min(gc)+max(gc))/2-(sw-1)/2)
            for lr in range(sh):
                for lc in range(sw):
                    rr=tr+lr;cc=tc+lc
                    if 0<=rr<H and 0<=cc<W:out[rr][cc]=grid[sr0+lr][sc0+lc]
    return out
